"kind": "propose",
"summary": "Renderer container's empty logs suggest memory issues, but CPU throttling remains the primary cause. Raise CPU limit to 1.5 cores to resolve throttling and liveness probe failures.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Renderer is throttled at 1 CPU limit (usage 0.93), with 41% throttling ratio, causing liveness failures despite empty logs.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "other",
    "summary": "Empty logs may indicate memory issues, but no evidence shows memory limits are exceeded or OOMKilled.",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise renderer's CPU limit from 1 to 1.5 cores to clear throttling and prevent liveness probe timeouts.",
  "rationale": "Throttling_data_available is true, cpu_throttled_at_limit and cpu_usage_near_limit are true, and liveness failures correlate with throttling. Empty logs may indicate memory issues but do not contradict CPU throttling as the root cause.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
